pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzedParam is the prospective caller who will attempt to change owner
    function testFuzz_property(address fuzzedParam, address newOwner) public {
        // Keep addresses wide but non-zero for meaningful actor
        vm.assume(fuzzedParam != address(0));
        vm.assume(newOwner != address(0));

        // Record owner before attempt
        address before = c.owner();

        // Have fuzzedParam attempt to call setOwner
        vm.prank(fuzzedParam);
        // call; we don't expect revert in either implementation, so just call
        c.setOwner(newOwner);

        // For the correct contract: only the admin (deployer) can change owner, so
        // after any call by an arbitrary address, owner must remain either unchanged
        // (if caller wasn't admin) or equal to newOwner only if caller was the admin.
        // We assert the universal property: if the caller is not the admin (the deployer),
        // owner must remain equal to before. This is a single assertion reading c.
        // Determine whether fuzzedParam equals the deployer (admin). The deployer is address(this) at setUp? No: c was deployed by this test contract in setUp(), so admin == address(this)

        if (fuzzedParam != address(this)) {
            // If caller is not admin, owner must not have changed
            assertTrue(c.owner() == before);
        } else {
            // If caller is admin (this test contract), owner should now equal newOwner
            // (the correct contract allows admin to set owner). We assert this as well
            // to keep the property precise for all inputs.
            assertTrue(c.owner() == newOwner);
        }
    }
}

