import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary caller address and an arbitrary candidate newOwner.
    // Rule: only the admin (the deployer) may change owner; therefore for any non-admin caller,
    // calling setOwner must NOT result in owner being changed (reference enforces this).
    function testFuzz_property(address caller, address candidateNewOwner) public {
        // Keep addresses wide but exclude the admin (which is address(this) since setUp deployed c from this test contract)
        address admin = address(this);
        vm.assume(caller != admin);
        // Also avoid zero-address candidate to keep domain reasonable (still wide)
        vm.assume(candidateNewOwner != address(0));

        // Snapshot the owner before the call
        address before = c.owner();

        // Simulate the caller calling setOwner
        vm.prank(caller);
        bool ok;
        try c.setOwner(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, on the correct contract non-admin callers cannot change owner.
        // So owner must remain equal to before regardless of whether the call reverted or succeeded.
        address after = c.owner();

        // Single assertion expressing the universal property: for all admissible inputs (caller != admin)
        // owner stays the same on the reference implementation. The mutant that removed onlyAdmin allows
        // some caller to change owner, so the fuzz will find such a case and make this assertion fail on the mutant.
        assertTrue(after == before);
    }
