import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller (address) and newOwner (address)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep addresses wide but avoid zero-address as owner to stay in sensible domain
        vm.assume(newOwner != address(0));

        // Ensure caller has some ETH so if setOwner were payable (it's not) it'd still work;
        // harmless for EOAs
        vm.deal(caller, 1 ether);

        bool ok;
        // make the call from `caller`'s context and capture whether it completed (did not revert)
        vm.startPrank(caller);
        try c.setOwner(newOwner) returns (bool r) {
            // Call completed; record returned boolean in okReturn
            ok = r;
        } catch {
            // Call reverted; mark as special sentinel (we assert only about non-reverting calls below)
            // use ok = false but we will only assert when call completed; to detect completion we re-call via low-level
            ok = false;
        }
        vm.stopPrank();

        // To determine if the call completed (non-reverting) we perform a low-level staticcall wrapper that
        // attempts to call setOwner and observes whether it reverts. staticcall will fail if the call reverts.
        // Build calldata for setOwner(address)
        bytes memory data = abi.encodeWithSignature("setOwner(address)", newOwner);
        (bool completed, bytes memory returned) = address(c).call(abi.encodePacked(data));
        // The above call is from this contract (not from `caller`), so it may revert due to admin check in reference.
        // We need to test the universal property: for ANY caller, IF their call completed then it must have returned true.
        // We therefore instead detect completion by replaying the call from the same caller via low-level call.
        vm.startPrank(caller);
        (bool completedFromCaller, bytes memory retFromCaller) = address(c).call(data);
        vm.stopPrank();

        // If the call from `caller` completed (did not revert), decode its returned bool and assert it is true.
        if (completedFromCaller) {
            // decode return data (could be empty, but setOwner returns bool on reference)
            bool ret = true;
            if (retFromCaller.length >= 32) {
                ret = abi.decode(retFromCaller, (bool));
            }
            // SINGLE ASSERT: the correct contract always returns true for successful setOwner calls;
            // the mutant can produce a successful call that returns false for some caller/newOwner pair.
            assertTrue(ret);
        }
    }
}

